mapper.select:
/* AppAdminEmployeeStatusMapper.selectAttdOwnerScope (Attd08Mapper.selectAttdOwnerScope 이식) */
    SELECT
          M.SITE_CD  AS siteCd
        , M.NODE_CD  AS nodeCd
        , M.USER_CD  AS userCd
    FROM TB_USER_ATTD_MGMT M
    WHERE M.CMPNY_CD = #{cmpnyCd}
      AND M.ATTD_ID  = #{attdId}
      AND M.DEL_YN   = 'N'
    LIMIT 1
